function estaBalanceado(s) {
  const pareja = { ')': '(', ']': '[', '}': '{' };
  const pila = [];
  for (const c of s) {
    if (c in pareja) {
      if (pila.pop() !== pareja[c]) return false;
    } else {
      pila.push(c);
    }
  }
  return pila.length === 0;
}

