def estaBalanceado(s):
    pareja = {')': '(', ']': '[', '}': '{'}
    pila = []
    for c in s:
        if c in pareja:
            if not pila or pila.pop() != pareja[c]:
                return False
        else:
            pila.append(c)
    return not pila
